package org.bytefred.ktoy.core

import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertNotNull
import kotlin.test.assertTrue

/**
 * Tests the example catalog (ExampleSources.kt, generated by
 * scripts/gen_example_sources.py):
 *
 *   1. [groupedExamples] returns the expected display categories, and a C
 *      example's compiler tags are right (a recursive one is toycc-only; a
 *      simple one lists both minicc and toycc).
 *   2. Every embedded C example compiles with ktoy's toycc and assembles
 *      cleanly, and where it declares `// expect: N`, running the compiled
 *      program to STOP leaves that value in ACC. This both verifies the
 *      embedded C sources and gives the C|asm feature verified data.
 */
class ExampleCatalogTest {

    private val SAFETY_CAP = 2_000_000
    private val EXPECT = Regex("""//\s*expect:\s*(\d+)""", RegexOption.IGNORE_CASE)

    private fun runToStop(machine: Machine, name: String) {
        var iterations = 0
        while (machine.step()) {
            iterations += 1
            assertTrue(
                iterations < SAFETY_CAP,
                "'$name' did not stop within $SAFETY_CAP iterations",
            )
        }
    }

    @Test
    fun groupingHasExpectedCategories() {
        val grouped = groupedExamples()
        // All four categories are populated (we embed ASM, C that only toycc
        // takes AND C that both take, and bytecode).
        assertEquals(
            listOf("Assembly", "C (minicc)", "C (toycc)", "Bytecode"),
            grouped.keys.toList(),
            "unexpected grouping categories / order",
        )
        for ((key, list) in grouped) {
            assertTrue(list.isNotEmpty(), "category '$key' is empty")
        }
        // Each category holds only examples of the matching kind / tag.
        assertTrue(grouped.getValue("Assembly").all { it.kind == ExampleKind.ASM })
        assertTrue(grouped.getValue("Bytecode").all { it.kind == ExampleKind.TOYO })
        assertTrue(grouped.getValue("C (minicc)").all {
            it.kind == ExampleKind.C && "minicc" in it.compilers
        })
        assertTrue(grouped.getValue("C (toycc)").all {
            it.kind == ExampleKind.C && "toycc" in it.compilers
        })
        // Every C example toycc accepts appears under "C (toycc)" (toycc is the
        // superset), so that category lists every embedded C example.
        val allC = EXAMPLES.count { it.kind == ExampleKind.C }
        assertEquals(allC, grouped.getValue("C (toycc)").size)
    }

    @Test
    fun recursiveIsToyccOnlyAndSimpleIsBoth() {
        // minicc rejects recursion; toycc compiles it. So a recursive example
        // lists only toycc, while a non-recursive one lists both.
        val rec = assertNotNull(
            EXAMPLES.firstOrNull { it.name == "fibonacci_rec.toyc" },
            "missing C example fibonacci_rec.toyc",
        )
        assertEquals(listOf("toycc"), rec.compilers, "recursive example must be toycc-only")

        val simple = assertNotNull(
            EXAMPLES.firstOrNull { it.name == "fibonacci_iter.toyc" },
            "missing C example fibonacci_iter.toyc",
        )
        assertEquals(
            listOf("minicc", "toycc"), simple.compilers,
            "simple iterative example must list both compilers",
        )
    }

    @Test
    fun everyCExampleCompilesAssemblesAndRunsToExpected() {
        val cExamples = EXAMPLES.filter { it.kind == ExampleKind.C }
        assertTrue(cExamples.isNotEmpty(), "no embedded C examples found")

        for (ex in cExamples) {
            // toycc is the compiler ktoy ships and the superset of what the
            // examples need, so every embedded C example must compile with it.
            assertTrue("toycc" in ex.compilers, "'${ex.name}' not tagged for toycc")

            val asm = compileSource(ex.source, ex.name)
            val result = assemble(asm)
            assertTrue(
                result.errors.isEmpty(),
                "'${ex.name}': assembling compiled output failed: " +
                    result.errors.joinToString("\n"),
            )

            val expect = EXPECT.find(ex.source)
            assertNotNull(expect, "'${ex.name}': no '// expect: N' marker in C source")
            val expectedAcc = expect.groupValues[1].toInt()

            val machine = Machine(result.mem, result.dataAddrs)
            runToStop(machine, ex.name)
            assertEquals(
                expectedAcc, machine.acc,
                "'${ex.name}': final ACC mismatch vs '// expect:'",
            )
        }
    }
}
